    public static Wish wish(SimState state, string kind, string? targetId = null)
    {
        return new Wish { kind = kind, targetId = targetId, since = state.tick, until = state.tick + Wishes.WISH_TICKS, promised = false };
    }

    public static void at(SimState state, int tick)
    {
        state.tick = tick;
        Wishes.updateWishes(state);
    }
    public static void at(SimState state, double tick) => at(state, (int)tick);

    /// <summary>wishes</summary>
    public class D001_wishes
