        [Fact(DisplayName = "wishes > turn up on the hour now and then, and only ones that fit")]
        public void T002_turn_up_on_the_hour_now_and_then_and_only_ones_that_fit()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = ["s.s.s.s.s.s"] });
            for (var h = 1; h <= 24; h++)
            {
                at(state, h * Time.TICKS_PER_HOUR);
            }
            var got = state.survivors.filter((s) => Js.T(s.wish));
            expect(got.length).toBeGreaterThan(0);
            foreach (var s in Js.Iter(got))
            {
                expect(Js.Arr(["hotMeal", "coat", "grave"])).not.toContain(Js.NN(s.wish).kind);
            }
        }

        [Fact(DisplayName = "wishes > met: a small lift")]
        public void T003_met_a_small_lift()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = ["s.."] });
            var s = Js.NN(Js.Get(state.survivors, 0));
            s.resolve = 50;
            s.wish = wish(state, "bed");
            at(state, 10);
            expect(s.wish).not.toBeNull();
            Mood.addThought(state, s, "sleptInBed");
            at(state, 20);
            expect(s.wish).toBeNull();
            expect(s.resolve).toBe(50 + Wishes.WISH_RESOLVE);
            expect(s.thoughts.some((t) => t.kind == "wishMet")).toBe(true);
        }

        [Fact(DisplayName = "wishes > a thought from before the wish began does not count")]
        public void T004_a_thought_from_before_the_wish_began_does_not_count()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = ["s.."] });
            var s = Js.NN(Js.Get(state.survivors, 0));
            Mood.addThought(state, s, "sleptInBed");
            state.tick = Js.I(100);
            s.wish = wish(state, "bed");
            at(state, 110);
            expect(s.wish).not.toBeNull();
        }

        [Fact(DisplayName = "wishes > promised and met: more, and they think better of you")]
        public void T005_promised_and_met_more_and_they_think_better_of_you()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = ["s.s"] });
            var (you, s) = state.survivors;
            Commands.applyCommand(state, new Command { type = "takeControl", survivorId = you.id });
            s.resolve = 50;
            s.wish = wish(state, "kill");
            expect(Commands.applyCommand(state, new Command { type = "promiseWish", survivorId = s.id })).toMatchObject(Js.Obj(("ok", (object?)(true))));
            expect(Commands.applyCommand(state, new Command { type = "promiseWish", survivorId = s.id }).ok).toBe(false);
            Mood.addThought(state, s, "bloodUp");
            at(state, 10);
            expect(s.resolve).toBe(50 + Wishes.PROMISE_RESOLVE);
            expect(Js.Get(s.opinions, you.id)).toBeGreaterThan(0);
        }

        [Fact(DisplayName = "wishes > promised and let run out: let down; unpromised and run out: nothing")]
        public void T006_promised_and_let_run_out_let_down_unpromised_and_run_out_not()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = ["s.s"] });
            var (you, s) = state.survivors;
            Commands.applyCommand(state, new Command { type = "takeControl", survivorId = you.id });
            s.resolve = 50;
            s.wish = wish(state, "weapon");
            at(state, Time.DAY_LENGTH + 10);
            expect(s.wish).toBeNull();
            expect(s.resolve).toBe(50);
            s.wish = wish(state, "weapon");
            Commands.applyCommand(state, new Command { type = "promiseWish", survivorId = s.id });
            at(state, (state.tick + Wishes.WISH_TICKS) + 10);
            expect(s.resolve).toBe(50 - Wishes.BROKEN_RESOLVE);
            expect(Js.Get(s.opinions, you.id)).toBeLessThan(0);
            expect(state.events.some((e) => Js.T(new JsRegExp("promise broken", "").test(e.message)))).toBe(true);
        }

